347			t.Errorf("before the child: bgSequences = %q, want [SET ... RESET]", before)
348		}
349		after := bgSequences(got[len(captured):])
350		if len(after) < 2 || after[0] != setOf(defaultHex()) || after[len(after)-1] != bgReset {
351			t.Errorf("after the child: bgSequences = %q, want [SET ... RESET]", after)
352		}
