1	// Package terminal provides terminal emulator auto-detection for opening new
2	// windows, tabs, or running commands in a detached terminal process.
3	package terminal
4	
5	import (
6		"os"
7		"os/exec"
8		"runtime"
9		"strings"
10	)
11	
12	// ForDir returns (binary, args, ok) to open a new terminal window at path.
13	// Returns ("", nil, false) when no supported terminal is detected.
14	func ForDir(path string) (string, []string, bool) {
15		// Windows Terminal (wt.exe) — works from WSL2 and native Windows
16		if os.Getenv("WT_SESSION") != "" {
17			if distro := os.Getenv("WSL_DISTRO_NAME"); distro != "" {
18				// Use -p to apply the WSL profile (fonts, background, etc.) and
19				// wsl.exe --cd for reliable directory navigation.
20				return "wt.exe", []string{"-p", distro, "--", "wsl.exe", "-d", distro, "--cd", path}, true
21			}
22			return "wt.exe", []string{"-d", path}, true
23		}
24		// Kitty
25		if os.Getenv("KITTY_WINDOW_ID") != "" {
26			return "kitty", []string{"--directory", path}, true
27		}
28		// WezTerm
29		if os.Getenv("WEZTERM_PANE") != "" || os.Getenv("WEZTERM_UNIX_SOCKET") != "" {
30			return "wezterm", []string{"start", "--cwd", path, "--", Shell()}, true
31		}
32		// Alacritty
33		if os.Getenv("ALACRITTY_SOCKET") != "" {
34			return "alacritty", []string{"--working-directory", path}, true
35		}
36		// COSMIC Terminal (System76/COSMIC Desktop)
37		if isCOSMICSession() {
38			if _, err := exec.LookPath("cosmic-term"); err == nil {
39				return "cosmic-term", []string{"--working-directory", path}, true
40			}
41		}
42		// VTE-based terminals (GNOME Terminal, XFCE4, Tilix)
43		if os.Getenv("VTE_VERSION") != "" {
44			if _, err := exec.LookPath("gnome-terminal"); err == nil {
45				return "gnome-terminal", []string{"--working-directory=" + path}, true
46			}
47			if _, err := exec.LookPath("xfce4-terminal"); err == nil {
48				return "xfce4-terminal", []string{"--working-directory", path}, true
49			}
50			if _, err := exec.LookPath("tilix"); err == nil {
51				return "tilix", []string{"--working-directory", path}, true
52			}
53		}
54		// TERM_PROGRAM (macOS / Hyper)
55		switch os.Getenv("TERM_PROGRAM") {
56		case "iTerm.app":
57			return "open", []string{"-a", "iTerm", path}, true
58		case "Hyper":
59			return "hyper", []string{path}, true
60		}
61		return "", nil, false
62	}
63	
64	// ForCmd returns (binary, args, ok) to open a new terminal window running innerArgs
65	// as the foreground command (e.g. []string{engine, "exec", "-it", id, "/bin/bash"}).
66	// Returns ("", nil, false) when no supported terminal is detected.
67	func ForCmd(innerArgs []string) (string, []string, bool) {
68		// Windows Terminal
69		if os.Getenv("WT_SESSION") != "" {
70			return "wt.exe", append([]string{"--"}, innerArgs...), true
71		}
72		// Kitty
73		if os.Getenv("KITTY_WINDOW_ID") != "" {
74			return "kitty", append([]string{"--"}, innerArgs...), true
75		}
76		// WezTerm
77		if os.Getenv("WEZTERM_PANE") != "" || os.Getenv("WEZTERM_UNIX_SOCKET") != "" {
78			return "wezterm", append([]string{"start", "--"}, innerArgs...), true
79		}
80		// Alacritty
81		if os.Getenv("ALACRITTY_SOCKET") != "" {
82			return "alacritty", append([]string{"-e"}, innerArgs...), true
83		}
84		// COSMIC Terminal
85		if isCOSMICSession() {
86			if _, err := exec.LookPath("cosmic-term"); err == nil {
87				return "cosmic-term", append([]string{"--"}, innerArgs...), true
88			}
89		}
90		// VTE-based terminals
91		if os.Getenv("VTE_VERSION") != "" {
92			if _, err := exec.LookPath("gnome-terminal"); err == nil {
93				return "gnome-terminal", append([]string{"--"}, innerArgs...), true
94			}
95			if _, err := exec.LookPath("xfce4-terminal"); err == nil {
96				return "xfce4-terminal", append([]string{"--"}, innerArgs...), true
97			}
98			if _, err := exec.LookPath("tilix"); err == nil {
99				return "tilix", append([]string{"--"}, innerArgs...), true
100			}
101		}
102		return "", nil, false
103	}
104	
105	// Shell returns the user's default shell, falling back to %COMSPEC% on Windows
106	// or /bin/sh on Unix.
107	func Shell() string {
108		if s := os.Getenv("SHELL"); s != "" {
109			return s
110		}
111		if runtime.GOOS == "windows" {
112			if s := os.Getenv("COMSPEC"); s != "" {
113				return s
114			}
115			return "cmd.exe"
116		}
117		return "/bin/sh"
118	}
119	
120	// isCOSMICSession returns true when running inside a COSMIC desktop session.
121	func isCOSMICSession() bool {
122		desktop := os.Getenv("XDG_CURRENT_DESKTOP")
123		return strings.Contains(strings.ToUpper(desktop), "COSMIC")
124	}
