type lockedBuffer struct {
	mu sync.Mutex
	b  bytes.Buffer
}

func (l *lockedBuffer) Write(p []byte) (int, error) { l.mu.Lock(); defer l.mu.Unlock(); return l.b.Write(p) }
func (l *lockedBuffer) String() string               { l.mu.Lock(); defer l.mu.Unlock(); return l.b.String() }

type instant struct{}

func (instant) Run() error          { return nil }
func (instant) SetStdin(io.Reader)  {}
func (instant) SetStdout(io.Writer) {}
func (instant) SetStderr(io.Writer) {}

// settled is the candidate workaround: Run never returns before settle has
// elapsed since it started.
type settled struct {
	tea.ExecCommand
	d time.Duration
}

func (s settled) Run() error {
	start := time.Now()
	err := s.ExecCommand.Run()
	if r := s.d - time.Since(start); r > 0 {
		time.Sleep(r)
	}
	return err
}

type doneMsg struct{}

type model struct {
	after bool
	exec  tea.ExecCommand
}

func (m *model) Init() tea.Cmd { return nil }
func (m *model) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
	switch msg.(type) {
	case tea.KeyPressMsg:
		return m, tea.Exec(m.exec, func(error) tea.Msg { return doneMsg{} })
	case doneMsg:
		m.after = true
	}
	return m, nil
}
func (m *model) View() tea.View {
	if m.after {
		return tea.NewView("AFTER-CHILD")
	}
	return tea.NewView("hello")
}

func wait(out *lockedBuffer, s string, d time.Duration) bool {
	dl := time.Now().Add(d)
	for !strings.Contains(out.String(), s) {
		if time.Now().After(dl) {
			return false
		}
		time.Sleep(2 * time.Millisecond)
	}
	return true
}

func once(ex tea.ExecCommand) bool {
	out := &lockedBuffer{}
	m := &model{exec: ex}
	p := tea.NewProgram(m, tea.WithInput(nil), tea.WithOutput(out), tea.WithWindowSize(80, 10), tea.WithoutSignalHandler())
	done := make(chan struct{})
	go func() { _, _ = p.Run(); close(done) }()
	if !wait(out, "hello", 2*time.Second) {
		panic("no first frame")
	}
	p.Send(tea.KeyPressMsg{Code: 'x', Text: "x"})
	ok := wait(out, "AFTER-CHILD", 500*time.Millisecond)
	p.Kill()
	<-done
	return ok
}

