	if *settle > 0 {
		ex = settled{instant{}, *settle}
	}
	stuck := 0
	for i := 0; i < *n; i++ {
		if !once(ex) {
			stuck++
		}
	}
	fmt.Fprintf(os.Stdout, "procs=%d settle=%v runs=%d stuck=%d\n", runtime.GOMAXPROCS(0), *settle, *n, stuck)
}
EOF
