package testutil

import (
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"io/fs"
	"os"
	"path/filepath"
	"sort"
	"strconv"
	"strings"
	"testing"
)

// DEVDESK-199 / DEVDESK-201: tests build key presses and pastes and pick a
// colour profile through the helpers in this package, never by hand. A hand-built
// tea.KeyPressMsg{Code: ..., Text: ...} or tea.PasteMsg{...} drifts from what
// the terminal really sends (the space key, alt+ without clearing Text), and
// a forced colour profile leaks a global across tests. This guard
// reads every *_test.go the way internal/ui/keymap's scans do, and names
// file:line for each offence.
//
// Using tea.KeyPressMsg or tea.KeyMsg as a TYPE (assertion, parameter,
// return) stays allowed. There is a single bubbletea import path since the
// module moved to charm.land/bubbletea/v2: the v1/v2 distinction this guard
// used to carry is gone.

const (
	bubbleteaPath    = "charm.land/bubbletea/v2"
	colorprofilePath = "github.com/charmbracelet/colorprofile"
)

// bannedKeyLiterals lists the types that must not be built as a composite literal.
var bannedKeyLiterals = map[string]bool{
	"KeyMsg": true, "KeyPressMsg": true, "KeyReleaseMsg": true, "Key": true, "PasteMsg": true,
}

// allowedKeySelectors are Key-prefixed names that stay allowed as types.
var allowedKeySelectors = map[string]bool{
	"KeyMsg": true, "KeyPressMsg": true, "KeyReleaseMsg": true, "KeyboardEnhancementsMsg": true,
}

// fieldSelectorExceptions lists "<slash path suffix>:<selector>" pairs allowed
// to use .Runes / .Alt / .Paste. Empty on purpose: every entry needs a reason
// written next to it.
var fieldSelectorExceptions = map[string]string{}

var bannedFields = map[string]bool{"Runes": true, "Alt": true, "Paste": true}

// colorprofileAllowed lists the test files that may name a colorprofile.Profile,
// each with its reason. A test that checks styling reads the SGR itself or
// strips it (ansi.Strip); only a test that runs a real tea.Program at a chosen
// profile needs the type.
var colorprofileAllowed = map[string]string{
	"internal/app/profile_test.go":                     "runs a real tea.Program at TrueColor, ANSI256 and Ascii",
	"internal/app/redraw_measure_test.go":              "runs a real tea.Program forced to TrueColor to match the v1 reference",
	"internal/app/terminal_background_test.go":         "maps each colour profile to the terminal background (DEVDESK-209)",
	"internal/app/terminal_background_program_test.go": "runs a real tea.Program at chosen profiles to read the background sequences (DEVDESK-209)",
}

// openTerminalInPlace suspends the TUI and opens a shell in the given directory.
func (m Model) openTerminalInPlace(targetPath string) (tea.Model, tea.Cmd) {
	shell := detectShell()
	if shell == "/bin/sh" {
		if _, err := os.Stat("/bin/bash"); err == nil {
			shell = "/bin/bash"
		}
	}
	cmd := exec.Command(shell)
	cmd.Dir = targetPath
	return m, tea.ExecProcess(cmd, func(err error) tea.Msg {
		if err != nil {
			log.Printf("ERROR [workspaces] terminal exit: %v", err)
		}
		return TerminalExitMsg{}
	})
}

// handleTerminalOpened handles the result of a non-blocking terminal launch.
		cmd, err := docker.BuildLaunchCmd(opts)
		if err != nil {
			log.Printf("ERROR [oci_resources] build launch cmd: %v", err)
			return m, m.footer.Error("Failed to launch container — check logs")
		}
		return m, tea.ExecProcess(cmd, func(err error) tea.Msg {
			if err != nil {
				log.Printf("ERROR [oci_resources] interactive container exit: %v", err)
			}
			return ContainerLaunchCompleteMsg{Err: err}
		})
	}

	shell := detectShell(c.ID)
	shellCmd := exec.Command(engine.Current().Binary, "exec", "-it", c.ID, shell) //nolint:gosec // same
	return m, tea.ExecProcess(shellCmd, func(err error) tea.Msg {
		return PagerExitMsg{Err: err}
	})
}

// shellSelectedContainerInNewWindow opens a shell in the selected container in a new
// terminal window using the auto-detected terminal emulator (non-blocking).
func (m Model) openPager() (tea.Model, tea.Cmd) {
	src, ok := m.pageable()
	if !ok {
		return m, nil
	}
	return m, tea.ExecProcess(src.PagerCmd(), func(err error) tea.Msg {
		return PagerExitMsg{Err: err}
	})
}

